<?php require_once 'config.php';require_login();$pdo=db();$year=(int)($_GET['year']??date('Y'));$month=max(1,min(12,(int)($_GET['month']??date('n'))));$account=(int)($_GET['account']??0);ensure_year($year);$accounts=$pdo->query('SELECT * FROM accounts WHERE active=1 ORDER BY id')->fetchAll();$selected=$account?$pdo->prepare('SELECT id,name FROM accounts WHERE id=?'):null;if($selected)$selected->execute([$account]);$accs=$account?($selected->fetchAll()):$accounts;$settings=$pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR);$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-d',strtotime($start.' +1 month'));$monthly=[];$annual=[];foreach($accs as $a){foreach(['USD','FC'] as $cur){$opening=balance_for((int)$a['id'],$year,$cur)['opening_amount'];$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) inc,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) exp FROM transactions WHERE account_id=? AND currency=? AND tx_date>=? AND tx_date<?");$q->execute([$a['id'],$cur,$start,$end]);$m=$q->fetch();$prior=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) FROM transactions WHERE account_id=? AND currency=? AND YEAR(tx_date)=? AND tx_date<?");$prior->execute([$a['id'],$cur,$year,$start]);$mo=$opening+(float)$prior->fetchColumn();$monthly[]=['account_name'=>$a['name'],'account_id'=>$a['id'],'currency'=>$cur,'opening'=>$mo,'income'=>$m['inc'],'expense'=>$m['exp'],'closing'=>$mo+(float)$m['inc']-(float)$m['exp']];$b=balance_for((int)$a['id'],$year,$cur);$annual[]=['account_name'=>$a['name'],'account_id'=>$a['id'],'currency'=>$cur]+$b;}}
$cq=$pdo->prepare('SELECT mi.*,a.name account_name,u.full_name closer FROM monthly_inventories mi JOIN accounts a ON a.id=mi.account_id LEFT JOIN users u ON u.id=mi.closed_by WHERE mi.year=? AND mi.month=?'.($account?' AND mi.account_id=?':'').' ORDER BY a.name,mi.currency');$cp=[$year,$month];if($account)$cp[]=$account;$cq->execute($cp);$closures=$cq->fetchAll();$special=$pdo->prepare("SELECT t.*,c.name category_name,u.full_name creator FROM transactions t LEFT JOIN categories c ON c.id=t.category_id LEFT JOIN users u ON u.id=t.created_by WHERE t.account_id=(SELECT id FROM accounts WHERE name='Offrandes spéciales' LIMIT 1) AND t.tx_date>=? AND t.tx_date<? ORDER BY t.tx_date,t.id");$special->execute([$start,$end]);$specialRows=$special->fetchAll();
// Classement automatique des dépenses à partir du seul libellé.
$categoryTotals=[];$categoryAnnual=[];
foreach([['start'=>$start,'end'=>$end,'target'=>&$categoryTotals],['start'=>sprintf('%04d-01-01',$year),'end'=>sprintf('%04d-01-01',$year+1),'target'=>&$categoryAnnual]] as &$period){
  $sql="SELECT label,currency,amount FROM transactions WHERE type='expense' AND tx_date>=? AND tx_date<?".($account?' AND account_id=?':'');
  $st=$pdo->prepare($sql);$args=[$period['start'],$period['end']];if($account)$args[]=$account;$st->execute($args);
  while($x=$st->fetch()){$catName=classify_label((string)$x['label']);$key=$catName.'|'.$x['currency'];$period['target'][$key]=($period['target'][$key]??0)+(float)$x['amount'];}
}
unset($period);
ksort($categoryTotals);ksort($categoryAnnual);
$page_title='Rapports et inventaires';include 'partials/header.php';?>
<div class="panel no-print"><div class="panel-head"><div><h2>Filtres des rapports</h2><p>Inventaire mensuel, trimestriel ou annuel par compte.</p></div><button class="btn primary" onclick="window.print()">Imprimer / Enregistrer PDF</button></div><form class="filter-row"><select name="account"><option value="0">Tous les comptes</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$account===$a['id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach?></select><select name="year"><?php for($y=date('Y')+1;$y>=date('Y')-10;$y--):?><option value="<?=$y?>" <?=$year===$y?'selected':''?>><?=$y?></option><?php endfor?></select><select name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor?></select><button class="btn">Afficher</button></form><a href="export.php?from=<?=$year?>-01-01&to=<?=$year?>-12-31">Exporter les opérations de l'année en Excel (CSV)</a></div>
<div class="report-head"><?php if(!empty($settings['logo_path'])):?><img src="<?=h($settings['logo_path'])?>" alt="Logo" style="max-width:90px;max-height:70px;object-fit:contain"><?php else:?><div class="brand-mark" style="margin:auto">EGD</div><?php endif?><h1><?=h($settings['church_name']??'EGLISE GERME DE DAVID')?></h1><p><?=h($settings['report_description']??'Rapport financier')?> · <?=h($year)?></p><small>Inventaire mensuel : <?=date('F',mktime(0,0,0,$month,1))?> <?=h($year)?></small></div>

<div class="panel"><h2>Somme des dépenses par libellé — <?=date('F',mktime(0,0,0,$month,1))?> <?=h($year)?></h2><p>La catégorie est reconnue automatiquement à partir des mots présents dans le libellé. Aucun champ catégorie n'est nécessaire.</p><div class="table-wrap"><table><tr><th>Catégorie détectée</th><th>USD</th><th>FC</th></tr><?php $names=[];foreach($categoryTotals as $k=>$v){$names[explode('|',$k)[0]]=true;}foreach(array_keys($names) as $n):?><tr><td><?=h($n)?></td><td class="num"><?=money($categoryTotals[$n.'|USD']??0,'USD')?></td><td class="num"><?=money($categoryTotals[$n.'|FC']??0,'FC')?></td></tr><?php endforeach?><tr><th>Total dépenses</th><th class="num"><?=money(array_sum(array_filter($categoryTotals,fn($k)=>str_ends_with($k,'|USD'),ARRAY_FILTER_USE_KEY)),'USD')?></th><th class="num"><?=money(array_sum(array_filter($categoryTotals,fn($k)=>str_ends_with($k,'|FC'),ARRAY_FILTER_USE_KEY)),'FC')?></th></tr></table></div></div>
<div class="panel"><h2>Somme annuelle par catégorie — <?=h($year)?></h2><div class="table-wrap"><table><tr><th>Catégorie détectée</th><th>USD</th><th>FC</th></tr><?php $names=[];foreach($categoryAnnual as $k=>$v){$names[explode('|',$k)[0]]=true;}foreach(array_keys($names) as $n):?><tr><td><?=h($n)?></td><td class="num"><?=money($categoryAnnual[$n.'|USD']??0,'USD')?></td><td class="num"><?=money($categoryAnnual[$n.'|FC']??0,'FC')?></td></tr><?php endforeach?></table></div></div>
<div class="panel"><h2>Offrandes ordinaires — modèle mensuel</h2><div class="table-wrap"><table><thead><tr><th>Mois</th><th>Devise</th><th>Solde initial</th><th>Entrée</th><th>Sortie</th><th>Solde</th><th>Solde cumulé</th></tr></thead><tbody><?php foreach($accs as $a):if($a['name']!=='Offrandes ordinaires')continue;foreach(['FC','USD'] as $cur):$cum=0;for($m=1;$m<=12;$m++):$st=sprintf('%04d-%02d-01',$year,$m);$en=date('Y-m-d',strtotime($st.' +1 month'));$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) i,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) e FROM transactions WHERE account_id=? AND currency=? AND tx_date>=? AND tx_date<?");$q->execute([$a['id'],$cur,$st,$en]);$x=$q->fetch();$cum+=(float)$x['i']-(float)$x['e'];$init=balance_for((int)$a['id'],$year,$cur)['opening_amount'];$prior=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) FROM transactions WHERE account_id=? AND currency=? AND YEAR(tx_date)=? AND tx_date<?");$prior->execute([$a['id'],$cur,$year,$st]);$op=$init+(float)$prior->fetchColumn();?><tr><td><?=date('F',strtotime($st))?></td><td><?=$cur?></td><td class="num"><?=money($op,$cur)?></td><td class="num"><?=money($x['i'],$cur)?></td><td class="num"><?=money($x['e'],$cur)?></td><td class="num"><?=money((float)$x['i']-(float)$x['e'],$cur)?></td><td class="num"><?=money($op+$cum,$cur)?></td></tr><?php endfor;endforeach;endforeach?></tbody></table></div></div>
<div class="panel"><h2>Inventaire détaillé de chaque compte — <?=date('F',mktime(0,0,0,$month,1))?></h2><div class="table-wrap"><table><thead><tr><th>Compte</th><th>Devise</th><th>Solde initial</th><th>Entrées</th><th>Sorties</th><th>Solde de clôture théorique</th></tr></thead><tbody><?php foreach($monthly as $r):?><tr><td><?=h($r['account_name'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($r['opening'],$r['currency'])?></td><td class="num"><?=money($r['income'],$r['currency'])?></td><td class="num"><?=money($r['expense'],$r['currency'])?></td><td class="num"><?=money($r['closing'],$r['currency'])?></td></tr><?php endforeach?></tbody></table></div></div>
<div class="panel"><h2>Offrandes spéciales — détail des mouvements</h2><p>Colonnes de suivi conformes au modèle fourni : date, entrée, sortie, libellé, solde et solde cumulé. Les devises sont maintenues distinctes.</p><div class="table-wrap"><table><tr><th>Date</th><th>Entrée</th><th>Sortie</th><th>Libellé</th><th>Devise</th><th>Solde cumulé</th><th>Enregistré par</th></tr><?php $specialBalances=[];foreach($specialRows as $r):$cur=$r['currency'];if(!isset($specialBalances[$cur])){$aid=(int)$r['account_id'];$specialBalances[$cur]=(float)balance_for($aid,$year,$cur)['opening_amount'];}$specialBalances[$cur]+=$r['type']==='income'?(float)$r['amount']:-((float)$r['amount']);?><tr><td><?=date('d/m/Y',strtotime($r['tx_date']))?></td><td><?=h($r['type']==='income'?money($r['amount'],$r['currency']):'—')?></td><td><?=h($r['type']==='expense'?money($r['amount'],$r['currency']):'—')?></td><td><?=h($r['label'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($specialBalances[$cur],$cur)?></td><td><?=h($r['creator']??'—')?></td></tr><?php endforeach?></table></div></div>
<div class="panel"><h2>Clôtures enregistrées pour le mois</h2><div class="table-wrap"><table><tr><th>Compte</th><th>Devise</th><th>Solde de clôture</th><th>Clôturé par</th><th>Date de clôture</th></tr><?php foreach($closures as $cl):?><tr><td><?=h($cl['account_name'])?></td><td><?=$cl['currency']?></td><td class="num"><?=money($cl['closing_amount'],$cl['currency'])?></td><td><?=h($cl['closer']??'—')?></td><td><?=h($cl['closed_at'])?></td></tr><?php endforeach?><?php if(!$closures):?><tr><td colspan="5">Aucune clôture enregistrée pour ce mois.</td></tr><?php endif?></table></div></div><div class="panel"><h2>Situation annuelle — <?=h($year)?></h2><div class="table-wrap"><table><tr><th>Compte</th><th>Devise</th><th>Solde initial</th><th>Entrées année</th><th>Sorties année</th><th>Solde final</th></tr><?php foreach($annual as $r):?><tr><td><?=h($r['account_name'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($r['opening_amount'],$r['currency'])?></td><td class="num"><?=money($r['income'],$r['currency'])?></td><td class="num"><?=money($r['expense'],$r['currency'])?></td><td class="num"><?=money($r['balance'],$r['currency'])?></td></tr><?php endforeach?></table></div></div>
<?php if(in_array(role(),['admin','treasurer'],true)):?><div class="panel no-print"><h2>Clôture / inventaire mensuel</h2><p>Une clôture est définitive et ne peut être enregistrée qu'une seule fois pour chaque compte et devise. Les corrections après clôture nécessitent une intervention administrative après sauvegarde.</p><form method="post" action="close_month.php" class="filter-row"><?=csrf_field()?><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$month?>"><select name="account_id"><option value="0">Tous les comptes</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['name'])?></option><?php endforeach?></select><button class="btn primary" onclick="return confirm('Confirmer la clôture ? Elle ne pourra pas être répétée.')">Effectuer la clôture</button></form></div><?php endif?><?php include 'partials/footer.php';?>